function [M, rhs] = eom_nonlinear(q, qd, F, P)
%EOM_NONLINEAR  Mass matrix and right-hand side of the planar tractor-semitrailer model.
%  Generated by derive.py (SymPy, Lagrange's equations, minimal coordinates).
%  q  = [X; Y; psi1; phi]   tractor CG position (m), tractor heading (rad), articulation angle (rad)
%  qd = time derivative of q
%  F  = [Fxf Fyf Fxr Fyr Fxt Fyt Mz1 Mz2]  axle forces in body frames (N) and L/R yaw moments (N m)
%  Solve qdd = M \ rhs.
  X=q(1); Y=q(2); psi1=q(3); phi=q(4); %#ok<NASGU>
  Xd=qd(1); Yd=qd(2); psi1d=qd(3); phid=qd(4); %#ok<NASGU>
  Fxf=F(1); Fyf=F(2); Fxr=F(3); Fyr=F(4); Fxt=F(5); Fyt=F(6); Mz1=F(7); Mz2=F(8);
  m1=P.m1; I1=P.I1; m2=P.m2; I2=P.I2; a1=P.a1; b1=P.b1; c1=P.c1; d2=P.d2; e2=P.e2;
  w0 = m1 + m2;
  w1 = sin(psi1);
  w2 = c1.*w1;
  w3 = phi - psi1;
  w4 = sin(w3);
  w5 = d2.*w4;
  w6 = m2.*(w2 - w5);
  w7 = m2.*w5;
  w8 = cos(psi1);
  w9 = c1.*w8;
  w10 = cos(w3);
  w11 = d2.*w10;
  w12 = -m2.*(w11 + w9);
  w13 = m2.*w11;
  w14 = d2.^2;
  w15 = c1.*cos(phi);
  w16 = d2.*m2;
  w17 = -I2 - w16.*(d2 + w15);
  w18 = psi1d.^2;
  w19 = (phid - psi1d).^2;
  w20 = Fyt.*d2;
  w21 = Fyt.*e2;
  w22 = c1.*sin(phi);
  w23 = w16.*w22;
  M = zeros(4,4); rhs = zeros(4,1);
  M(1,1) = w0;
  M(1,2) = 0;
  M(1,3) = w6;
  M(1,4) = w7;
  M(2,1) = 0;
  M(2,2) = w0;
  M(2,3) = w12;
  M(2,4) = w13;
  M(3,1) = w6;
  M(3,2) = w12;
  M(3,3) = I1 + I2 + m2.*(c1.^2 + 2*d2.*w15 + w14);
  M(3,4) = w17;
  M(4,1) = w7;
  M(4,2) = w13;
  M(4,3) = w17;
  M(4,4) = I2 + m2.*w14;
  rhs(1) = Fxf.*w8 + Fxr.*w8 + Fxt.*w10 - Fyf.*w1 - Fyr.*w1 + Fyt.*w4 - m2.*(w11.*w19 + w18.*w9);
  rhs(2) = Fxf.*w1 + Fxr.*w1 - Fxt.*w4 + Fyf.*w8 + Fyr.*w8 + Fyt.*w10 - m2.*(w18.*w2 - w19.*w5);
  rhs(3) = Fxt.*w22 + Fyf.*a1 - Fyr.*b1 - Fyt.*w15 + Mz1 + Mz2 - phid.^2.*w23 + 2*phid.*psi1d.*w23 - w20 - w21;
  rhs(4) = -Mz2 - w18.*w23 + w20 + w21;
end
